class GuildActions:
  """The actions of a guild: what its ref can do, on the object."""

  def _ref(self) -> GuildRef:
    me: Any = self
    return me.context.api.guild(me.id)

  def member(self, user_id: int | str) -> MemberRef:
    """The member with this id."""
    return self._ref().member(user_id)

  def role(self, role_id: int | str) -> RoleRef:
    """The role with this id."""
    return self._ref().role(role_id)

  def emoji(self, emoji_id: int | str) -> EmojiRef:
    """The emoji with this id."""
    return self._ref().emoji(emoji_id)

