class RoleActions:
  """The actions of a role: what its ref can do, on the object."""

  def _ref(self) -> RoleRef:
    me: Any = self
    if me.guild_id is None:
      raise RuntimeError("This Role does not know its guild_id, so it cannot act.")
    return me.context.api.role(me.guild_id, me.id)

  async def fetch(self) -> Result[m.GuildRoleResponse, DiscordAPIError]:
    """GET /guilds/{guild_id}/roles/{role_id}"""
    return await self._ref().get()

  async def edit(
    self,
    *,
    name: str | None = UNSET,
    permissions: int | None = UNSET,
    color: int | None = UNSET,
    colors: m.RoleColors | Mapping[str, Any] | None = UNSET,
    hoist: bool | None = UNSET,
    mentionable: bool | None = UNSET,
    icon: str | None = UNSET,
    unicode_emoji: str | None = UNSET,
    reason: str | None = None,
  ) -> Result[m.GuildRoleResponse, DiscordAPIError]:
    """PATCH /guilds/{guild_id}/roles/{role_id}"""
    return await self._ref().edit(
      name=name,
      permissions=permissions,
      color=color,
      colors=colors,
      hoist=hoist,
      mentionable=mentionable,
      icon=icon,
      unicode_emoji=unicode_emoji,
      reason=reason,
    )

  async def delete(self, *, reason: str | None = None) -> Result[None, DiscordAPIError]:
    """DELETE /guilds/{guild_id}/roles/{role_id}"""
    return await self._ref().delete(reason=reason)
